/**
 * Reads from IndexedDB and re-reads whenever the data changes.
 *
 * Dexie's own live queries drive this, so a mutation anywhere in the app
 * updates every screen showing that data without a store, an event bus or
 * a manual refresh. The initial value is returned on the first render, so a
 * screen never has to handle "undefined while loading".
 */
import { liveQuery } from 'dexie';
import { useEffect, useState } from 'react';

/**
 * Subscribes to a query. `deps` behaves like an effect's dependency list:
 * change it and the query is rebuilt.
 */
export function useLiveQuery<T>(query: () => Promise<T>, initial: T, deps: readonly unknown[]): T {
  const [value, setValue] = useState<T>(initial);

  useEffect(() => {
    // A query already in flight when the deps change can still resolve after
    // the subscription is dropped. Without this guard its stale result would
    // land last and win, which shows as a search that lags a keystroke.
    let live = true;
    const subscription = liveQuery(query).subscribe({
      next: (next) => {
        if (live) setValue(next);
      },
      error: (error: unknown) => {
        // A failed local read is a bug worth seeing, but it must not blank
        // the screen: the last good value stays on show.
        if (live) console.error('live query failed', error);
      },
    });
    return () => {
      live = false;
      subscription.unsubscribe();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return value;
}
